const out = [];
const names = ['FITC-', 'PE-Vio770-', 'PE-', 'BUV395-', 'BV605+', 'BV786+', 'BV605-', 'BV786-'];
rep.compare.forEach(r => {
  const leaf = r.path.split('/').pop();
  if (names.indexOf(leaf) < 0) return;
  const s = ws.samples.find(x => x.key === r.sample);
  const g = FM.gating.gateFor(ws.gate(r.gateId), s.key);
  const par = ws.gate(r.gateId).parent;
  const pidx = ws.indices(s, par);
  const rawSample = { name: s.name, data: s.raw || s.data };
  out.push({ file: r.file, path: r.path, flowmate: r.ours, onRaw: FM.gating.filter(g, rawSample, pidx).length, x: g.x, y: g.y });
});
return out;
